// Package codex implements a minimal JSON-RPC client for `codex
// app-server` over stdio or WebSocket.
//
// Framing is newline-delimited JSON (one message per line), not LSP-style
// Content-Length headers. Codex's JSON-RPC variant omits the "jsonrpc"
// version field: a request is {id, method, params?}, a notification is
// {method, params?}, and a response is {id, result?} or {id, error?}.
// The message schema is generated by `codex app-server generate-json-schema`
// (see internal/wire/codex/schema/).
//
// A stricter peer can opt into standard JSON-RPC 2.0 envelopes through
// Client.JSONRPCVersion without changing Codex's existing wire shape.
package codex

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os/exec"
	"sync"

	"github.com/dkroshow/nano/internal/wire"
)

const (
	Send = wire.Send
	Recv = wire.Recv
)

// WireLogger observes raw JSON-RPC messages in the direction they traveled.
type WireLogger func(dir wire.Direction, line []byte)

// Message is one decoded JSON-RPC message of any kind. Exactly one of the
// request/notification/response field sets is populated.
type Message struct {
	ID     *json.RawMessage `json:"id,omitempty"`
	Method string           `json:"method,omitempty"`
	Params json.RawMessage  `json:"params,omitempty"`
	Result json.RawMessage  `json:"result,omitempty"`
	Error  *RPCError        `json:"error,omitempty"`
}

// RPCError is the JSON-RPC error object.
type RPCError struct {
	Code    int             `json:"code"`
	Message string          `json:"message"`
	Data    json.RawMessage `json:"data,omitempty"`
}

func (e *RPCError) Error() string {
	return fmt.Sprintf("rpc error %d: %s", e.Code, e.Message)
}

// IsRequest reports whether the message expects a response.
func (m *Message) IsRequest() bool { return m.ID != nil && m.Method != "" }

// IsNotification reports whether the message is a fire-and-forget event.
func (m *Message) IsNotification() bool { return m.ID == nil && m.Method != "" }

// IsResponse reports whether the message answers one of our requests.
func (m *Message) IsResponse() bool { return m.ID != nil && m.Method == "" }

// transport moves one JSON-RPC message at a time. readMessage must return a
// buffer that stays valid after the next call (i.e. a copy, if the underlying
// reader reuses its buffer).
type transport interface {
	start() error
	writeMessage(line []byte) error
	readMessage() ([]byte, error)
	close() error
}

// Client multiplexes JSON-RPC traffic with a codex app-server over a
// transport (a spawned child's stdio, or a websocket to a daemon).
type Client struct {
	tr transport

	// OnNotification receives every server notification. Set before Start.
	OnNotification func(method string, params json.RawMessage)
	// OnServerRequest receives server→client requests (approvals etc.) and
	// must return a result or an error to send back. Set before Start.
	//
	// It runs ON THE READ LOOP, so a handler that blocks stalls every session
	// sharing the connection. A handler that cannot answer immediately —
	// anything a human has to decide — returns Deferred instead and answers
	// later with RespondToServerRequest, quoting the requestID it was given
	// here (the raw JSON-RPC id, verbatim, which is also how a multiplexed
	// daemon keys its own routing of the eventual response).
	OnServerRequest func(requestID string, method string, params json.RawMessage) (any, *RPCError)
	// WireLog, if set, observes every raw line in both directions unless a
	// specific request supplied its own wire logger.
	WireLog WireLogger
	// JSONRPCVersion, when non-empty, is included as the "jsonrpc" field on
	// every outbound request, notification, and response. Codex clients leave
	// it empty; ACP clients set it to "2.0" before Start.
	JSONRPCVersion string

	writeMu sync.Mutex
	mu      sync.Mutex
	nextID  int64
	pending map[int64]pendingCall
	// deferredRequests holds the raw ids of server→client requests a handler
	// took ownership of. An id lives here from the moment dispatch skips
	// responding until RespondToServerRequest claims it, which is what makes
	// answering exactly-once without the id being lost in the meantime.
	deferredRequests map[string]json.RawMessage
	done             chan struct{}
	readErr          error
}

// deferredResult is the sentinel type an OnServerRequest handler returns to say
// "I own this reply now". A distinct unexported type so no ordinary result
// value can be mistaken for it.
type deferredResult struct{}

// Deferred is returned by an OnServerRequest handler that will answer later via
// RespondToServerRequest. Dispatch then sends nothing and remembers the request
// id, leaving the read loop free for every other session on the connection.
var Deferred any = deferredResult{}

// ErrRequestNotDeferred means the request id is not awaiting a deferred
// response: it was never deferred, or it has already been answered. Callers
// treat it as "someone else got there first", not as a fault — answering is
// idempotent by design (a second tab, or a teardown racing a click).
var ErrRequestNotDeferred = errors.New("protocol: server request is not awaiting a deferred response")

// ErrClientClosed means the connection this request arrived on is gone, so the
// answer has nowhere to go. The request died with the connection.
var ErrClientClosed = errors.New("protocol: client connection closed")

// RespondToServerRequest answers a request whose handler returned Deferred.
// Idempotent: the first call claims the id, later calls report
// ErrRequestNotDeferred rather than writing a second response. The write goes
// through the same WireLog path a synchronous response takes, so a multiplexed
// daemon's id-keyed routing lands it in the owning session's buffer.
func (c *Client) RespondToServerRequest(requestID string, result any, rpcErr *RPCError) error {
	c.mu.Lock()
	raw, ok := c.deferredRequests[requestID]
	if ok {
		delete(c.deferredRequests, requestID)
	}
	c.mu.Unlock()
	if !ok {
		return ErrRequestNotDeferred
	}
	select {
	case <-c.done:
		return ErrClientClosed
	default:
	}
	return c.respond(raw, result, rpcErr)
}

// DeferredRequestIDs lists the requests still awaiting an answer. Teardown uses
// it to make sure nothing is left parked on the far side.
func (c *Client) DeferredRequestIDs() []string {
	c.mu.Lock()
	defer c.mu.Unlock()
	ids := make([]string, 0, len(c.deferredRequests))
	for id := range c.deferredRequests {
		ids = append(ids, id)
	}
	return ids
}

type pendingCall struct {
	ch      chan *Message
	wireLog WireLogger
}

func newClient(tr transport) *Client {
	return &Client{
		tr:               tr,
		pending:          make(map[int64]pendingCall),
		deferredRequests: make(map[string]json.RawMessage),
		done:             make(chan struct{}),
	}
}

// NewClient prepares (but does not start) a client running `codex app-server`
// with the given extra CLI args, speaking newline-JSON over its stdio.
func NewClient(args ...string) *Client {
	return NewClientCmd(exec.Command("codex", append([]string{"app-server"}, args...)...))
}

// NewClientCmd prepares (but does not start) a newline-JSON client backed by
// an arbitrary child process. A nil command is accepted here so construction
// stays panic-free; Start reports errNilCommand.
func NewClientCmd(cmd *exec.Cmd) *Client {
	return newClient(&stdioTransport{cmd: cmd})
}

// NewClientWS prepares (but does not start) a client that dials a running
// app-server daemon over websocket (`codex app-server --listen ws://…` or
// `unix://…`); each JSON-RPC message rides one text frame.
func NewClientWS(url string) *Client {
	return newClient(&wsTransport{url: url})
}

// Start opens the transport and the read loop.
func (c *Client) Start() error {
	if err := c.tr.start(); err != nil {
		return err
	}
	go c.readLoop()
	return nil
}

// StartContext is the deadline-aware variant used by hosted callers that must
// not wait behind an unbounded daemon dial. Legacy transports still fall back
// to Start; the built-in WebSocket transport honors the context in DialContext.
func (c *Client) StartContext(ctx context.Context) error {
	if ctx == nil {
		ctx = context.Background()
	}
	if starter, ok := c.tr.(interface{ startContext(context.Context) error }); ok {
		if err := starter.startContext(ctx); err != nil {
			return err
		}
	} else if err := c.tr.start(); err != nil {
		return err
	}
	go c.readLoop()
	return nil
}

// Close tears down the transport (killing the child process, if any).
func (c *Client) Close() error {
	return c.tr.close()
}

// Done is closed when the read loop exits — the transport closed or the
// app-server process died.
func (c *Client) Done() <-chan struct{} { return c.done }

// Call sends a request and waits for its response or ctx cancellation.
func (c *Client) Call(ctx context.Context, method string, params any, result any) error {
	return c.call(ctx, method, params, result, nil, nil)
}

// CallWithWireLog sends a request and routes the raw request/response pair to
// wireLog. This lets a multiplexed daemon client attribute individual calls to
// the session that made them, while connection-scoped notifications still use
// Client.WireLog.
func (c *Client) CallWithWireLog(ctx context.Context, method string, params any, result any, wireLog WireLogger) error {
	return c.call(ctx, method, params, result, wireLog, nil)
}

// CallWithWriteAck invokes written after the request has reached the
// transport, before any concurrently arriving response or notification is
// dispatched. Grok uses this narrow hook to arm prompt-id adoption only after
// session/prompt was actually written.
func (c *Client) CallWithWriteAck(ctx context.Context, method string, params any, result any, written func()) error {
	return c.call(ctx, method, params, result, nil, written)
}

func (c *Client) call(ctx context.Context, method string, params any, result any, wireLog WireLogger, written func()) error {
	c.mu.Lock()
	c.nextID++
	id := c.nextID
	ch := make(chan *Message, 1)
	c.pending[id] = pendingCall{ch: ch, wireLog: wireLog}
	c.mu.Unlock()

	defer func() {
		c.mu.Lock()
		delete(c.pending, id)
		c.mu.Unlock()
	}()

	if err := c.writeMessageWithLogAndAck(c.envelope(map[string]any{"id": id, "method": method, "params": params}), wireLog, written); err != nil {
		return err
	}
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-c.done:
		return fmt.Errorf("app-server exited while waiting for %s: %w", method, c.readErr)
	case resp := <-ch:
		if resp.Error != nil {
			return resp.Error
		}
		if result != nil {
			return json.Unmarshal(resp.Result, result)
		}
		return nil
	}
}

// Notify sends a notification (no response expected).
func (c *Client) Notify(method string, params any) error {
	msg := map[string]any{"method": method}
	if params != nil {
		msg["params"] = params
	}
	return c.writeMessageWithLog(c.envelope(msg), nil)
}

func (c *Client) respond(id json.RawMessage, result any, rpcErr *RPCError) error {
	msg := map[string]any{"id": id}
	if rpcErr != nil {
		msg["error"] = rpcErr
	} else {
		msg["result"] = result
	}
	return c.writeMessageWithLog(c.envelope(msg), nil)
}

func (c *Client) envelope(msg map[string]any) map[string]any {
	if c.JSONRPCVersion != "" {
		msg["jsonrpc"] = c.JSONRPCVersion
	}
	return msg
}

func (c *Client) writeMessageWithLog(msg any, wireLog WireLogger) error {
	return c.writeMessageWithLogAndAck(msg, wireLog, nil)
}

func (c *Client) writeMessageWithLogAndAck(msg any, wireLog WireLogger, written func()) error {
	line, err := json.Marshal(msg)
	if err != nil {
		return err
	}
	switch {
	case wireLog != nil:
		wireLog(Send, line)
	case c.WireLog != nil:
		c.WireLog(Send, line)
	}
	c.writeMu.Lock()
	defer c.writeMu.Unlock()
	if err := c.tr.writeMessage(line); err != nil {
		return err
	}
	if written != nil {
		written()
	}
	return nil
}

func (c *Client) readLoop() {
	for {
		line, err := c.tr.readMessage()
		if err != nil {
			c.readErr = err
			break
		}
		var msg Message
		if err := json.Unmarshal(line, &msg); err != nil {
			continue // not JSON-RPC; ignore (stderr goes elsewhere already)
		}
		c.dispatch(&msg, line)
	}
	close(c.done)
}

func (c *Client) dispatch(msg *Message, line []byte) {
	// A read can complete on another goroutine immediately after a request
	// write. Cross the write mutex before dispatch so CallWithWriteAck's hook
	// always runs first.
	c.writeMu.Lock()
	c.writeMu.Unlock()
	switch {
	case msg.IsResponse():
		var id int64
		if err := json.Unmarshal(*msg.ID, &id); err != nil {
			return // string ids are only used by the server's own requests
		}
		c.mu.Lock()
		pending := c.pending[id]
		c.mu.Unlock()
		switch {
		case pending.wireLog != nil:
			pending.wireLog(Recv, line)
		case c.WireLog != nil:
			c.WireLog(Recv, line)
		}
		if pending.ch != nil {
			pending.ch <- msg
		}
	case msg.IsRequest():
		if c.WireLog != nil {
			c.WireLog(Recv, line)
		}
		var result any
		var rpcErr *RPCError
		if c.OnServerRequest != nil {
			result, rpcErr = c.OnServerRequest(string(*msg.ID), msg.Method, msg.Params)
		} else {
			rpcErr = &RPCError{Code: -32601, Message: "no server-request handler"}
		}
		if _, deferred := result.(deferredResult); deferred && rpcErr == nil {
			// The handler owns the reply. Keep the id — dropping it here is
			// what would strand the request forever — and move on: the read
			// loop must not wait for a human.
			c.mu.Lock()
			c.deferredRequests[string(*msg.ID)] = append(json.RawMessage(nil), *msg.ID...)
			c.mu.Unlock()
			return
		}
		c.respond(*msg.ID, result, rpcErr)
	case msg.IsNotification():
		if c.WireLog != nil {
			c.WireLog(Recv, line)
		}
		if c.OnNotification != nil {
			c.OnNotification(msg.Method, msg.Params)
		}
	}
}
